import nodemailer from "nodemailer";
const transport = nodemailer.createTransport({
  host: process.env.SMTP_HOST, port: 587, secure: false,
  requireTLS: true,
  auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS },
});
export async function verifyMailServer() {
  await transport.verify();
  return { ready: true };
}

exercise.solution:
في فهم SMTP عبر Nodemailer يحافظ الحل على سلطة واحدة ويطبق تحديدًا «مطابقة المنفذ ووضع TLS بوثائق المزوّد والتحقق في الخادم وعدم بدء الأسرار بـ NEXT_PUBLIC». يجعل يُجمع secure true مع منفذ STARTTLS 587 أو تُستورد أسرار SMTP في مكوّن عميل قابلًا للتكرار ثم مضبوطًا ولا يُقبل إلا عندما ينجح transport.verify في بيئة الخادم المسموحة ويفشل بوضوح عند خطأ المضيف أو المنفذ أو TLS أو الاعتماد.
